package game

import "github.com/google/uuid"

// exile_effect_grants.go — an ability a RESOLVED effect gives a card in
// exile (ADR 0219, #4973).
//
//	CR 113.10  "Effects can add or remove abilities of objects. An effect
//	           that adds an ability will state that the object 'gains' or
//	           'has' that ability, or similar."
//	CR 611.2a  "A continuous effect generated by the resolution of a spell
//	           or ability lasts as long as stated by the spell or ability
//	           creating it … If no duration is stated, it lasts until the
//	           end of the game."
//	CR 400.7   "An object that moves from one zone to another becomes a
//	           new object with no memory of, or relation to, its previous
//	           existence."
//
// Q, Stacking the Deck is the card: "That nonland card gains 'Exile a card
// from your hand: Create a copy of this card. You may cast the copy.
// Activate only during your turn and only if this card is exiled.'" The
// card is in exile, the grant comes from a trigger that has resolved, and
// nothing on the battlefield keeps it alive, so neither of the two earlier
// homes fits: a static's zone grant (zone_grants.go) is re-derived every
// pass from a source that is still there, and Card.GrantedAbilities is a
// copiable value (CR 707.2) that a copy of the card would wrongly inherit.
//
// # The shape
//
// Card.ExileGrants holds the GrantedAbility rows, the same plain data a
// zone grant writes (bundle key, grantor, activator), and nothing else:
// no closure, no pointer. The one ability-row accessor reads them beside
// the zone grants (abilityGrantsOf), so the activation path, the wire's
// zone_abilities row, the legal-move enumerator and a restored stack
// item's "grant:<bundle>:<i>:<n>" ref all see the row with no change of
// their own. The bundle is an ordinary exile-zone AbilityGrant, so its
// own declaration (ActivatedAbility.Zones) holds the activation to exile.
//
// # When it ends
//
// It is a property of the object (CR 400.7): MoveCard clears it on every
// zone change, beside SuspendGranted, so a card that leaves exile, even
// straight back into exile, is a new object without it. It is carried by
// the snapshot (additive within the version), because unlike a zone grant
// there is no source to rebuild it from.

// GrantAbilityToExiledCardForEffect gives the card `cardID`, which must be
// in exile, the bundle named `key` (a catalog grant key without the
// "grant:" prefix, or with it). `source` is the granting object, for the
// wire label; `activator` is the "you" of the granting effect. A card that
// is no longer in exile is left alone (CR 608.2b), and an empty key gives
// nothing. Reports whether the grant landed.
//
// Caller must hold g.mu (write).
func (g *Game) GrantAbilityToExiledCardForEffect(cardID, source, activator uuid.UUID, key string) bool {
	gk := GrantKey(key)
	if gk == "" {
		return false
	}
	c := exiledCardByIDLocked(g, cardID)
	if c == nil {
		return false
	}
	// Always a fresh slice, never written in place: a clone or a view may
	// share the old one.
	out := make([]GrantedAbility, 0, len(c.ExileGrants)+1)
	out = append(out, c.ExileGrants...)
	c.ExileGrants = append(out, GrantedAbility{Key: gk, Source: source, Activator: activator})
	return true
}

// ExileGrantSnapshot is one Card.ExileGrants row on disk.
type ExileGrantSnapshot struct {
	Key       string    `json:"key"`
	Source    uuid.UUID `json:"source,omitempty"`
	Activator uuid.UUID `json:"activator,omitempty"`
	// UntilEndOfTurn is additive within the snapshot version: absent on
	// every older point, which reads as false.
	UntilEndOfTurn bool `json:"untilEndOfTurn,omitempty"`
}

func exileGrantsToSnapshot(in []GrantedAbility) []ExileGrantSnapshot {
	if len(in) == 0 {
		return nil
	}
	out := make([]ExileGrantSnapshot, len(in))
	for i, gr := range in {
		out[i] = ExileGrantSnapshot(gr)
	}
	return out
}

func exileGrantsFromSnapshot(in []ExileGrantSnapshot) []GrantedAbility {
	if len(in) == 0 {
		return nil
	}
	out := make([]GrantedAbility, 0, len(in))
	for _, s := range in {
		if s.Key == "" {
			continue
		}
		out = append(out, GrantedAbility(s))
	}
	if len(out) == 0 {
		return nil
	}
	return out
}
